import numpy as np
F=np.load('source_pixels.npz')['rgb'].astype(np.int16)
for t in [0,1,5,10,20,28,30,35,40,60,95]:
 print('\\nFRAME',t)
 # rows with high chroma bbox all image excluding blue
 for y in range(55,100):
  seg=[]
  for x in range(0,256):
   R,G,B=map(int,F[t,y,x])
   if R>100 and G>80 and B<140 and R>B+30 and G>B+20: seg.append(('Y',x))
   elif R>150 and G<150 and B<170 and R>G+25: seg.append(('R',x))
  if seg:
   # compress type,x ranges
   groups=[]
   for typ,x in seg:
    if groups and groups[-1][0]==typ and x==groups[-1][2]+1:groups[-1]=(typ,groups[-1][1],x)
    else:groups.append((typ,x,x))
   print(y,' '.join(f'{a}{b}-{c}' for a,b,c in groups))
