import numpy as np
F=np.load('source_pixels.npz')['rgb'].astype(np.int16)
# compare frame0 to frames 20/30/60 where stone absent: pixelwise max abs in stone full area
for t in [1,5,10,20,28,30,35,40,60,95]:
 print('\\n',t)
 for y in range(70,89):
  # x 202..225 diffs > 15
  vals=[]
  for x in range(202,225):
   d=np.max(np.abs(F[t,y,x]-F[0,y,x]))
   if d>15:vals.append((x,int(d)))
  if vals: print(y,vals)
